def compute(vars):
    operating_profit_margin = vars["Operating Profit Margin"]
    revenue = vars["Revenue"]

    operating_profit_margin_ratio = operating_profit_margin / 100
    operating_income = operating_profit_margin_ratio * revenue

    return {
        "value": operating_income,
        "trace": {
            "Operating Profit Margin": operating_profit_margin,
            "Operating Profit Margin (ratio)": operating_profit_margin_ratio,
            "Revenue": revenue,
            "output_meta": {
                "currency": "$",
                "scale": None,
                "unit": None
            }
        }
    }
